import 'package:flutter/material.dart';
import '../services/cloud_service.dart';
import 'login_screen.dart';
class ProfileScreen extends StatefulWidget{const ProfileScreen({super.key});@override State<ProfileScreen> createState()=>_ProfileScreenState();}
class _ProfileScreenState extends State<ProfileScreen>{final cloud=CloudService();final p1=TextEditingController();final p2=TextEditingController();String? msg;bool busy=false;Future<void> change()async{if(p1.text.length<6||p1.text!=p2.text){setState(()=>msg='Mật khẩu mới tối thiểu 6 ký tự và phải trùng nhau.');return;}setState(()=>busy=true);try{await cloud.changePassword(p1.text);if(mounted)setState(()=>msg='Đổi mật khẩu thành công.');p1.clear();p2.clear();}catch(e){if(mounted)setState(()=>msg=e.toString());}finally{if(mounted)setState(()=>busy=false);}}Future<void> logout()async{await cloud.signOut();if(!mounted)return;Navigator.of(context).pushAndRemoveUntil(MaterialPageRoute(builder:(_)=>const LoginScreen()),(_)=>false);}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Tài khoản')),body:ListView(padding:const EdgeInsets.all(16),children:[Text(cloud.user?.email??'',style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:20),TextField(controller:p1,obscureText:true,decoration:const InputDecoration(labelText:'Mật khẩu mới',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:p2,obscureText:true,decoration:const InputDecoration(labelText:'Nhập lại mật khẩu',border:OutlineInputBorder())),if(msg!=null)Padding(padding:const EdgeInsets.all(12),child:Text(msg!)),const SizedBox(height:8),FilledButton(onPressed:busy?null:change,child:const Text('ĐỔI MẬT KHẨU')),const SizedBox(height:12),OutlinedButton.icon(onPressed:logout,icon:const Icon(Icons.logout),label:const Text('ĐĂNG XUẤT'))]));}
